// naming-topics.js
(()=>{const labels={};if(new URLSearchParams(location.search).get('topic')==='alcohol'){location.replace('alcohol-naming.html?v=321');return;}if(new URLSearchParams(location.search).get('topic')==='alkyne'){location.replace('alkyne-naming.html?v=319');return;}if(new URLSearchParams(location.search).get('topic')==='alkene'){location.replace('alkene-naming.html?v=317');return;}if(new URLSearchParams(location.search).get('topic')==='alkyl-halide'){location.replace('halide-naming.html?v=310');return;}function show(){const topic=new URLSearchParams(location.search).get('topic'),valid=Object.hasOwn(labels,topic);document.querySelector('#naming-topic-notice').hidden=!valid;document.querySelector('#naming-topic-title').textContent=valid?labels[topic]:'';document.querySelectorAll('[data-naming-topic]').forEach(card=>{if(card.dataset.namingTopic===topic)card.setAttribute('aria-current','true');else card.removeAttribute('aria-current')})}document.querySelectorAll('[data-naming-topic]').forEach(card=>card.addEventListener('click',event=>{if(event.button||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;event.preventDefault();history.pushState({},'',card.href);show()}));window.addEventListener('popstate',show);show()})();
